-- Supersede the mig-140 hand-seeded deck atoms (no cocoon/anchor) — soft-archive, reversible.
UPDATE library_atoms SET archived_at = COALESCE(archived_at, now()), updated_at = now()
WHERE tenant_id = (SELECT id FROM tenants WHERE slug='foundation') AND source = 'upload' AND cocoon_id IS NULL
  AND grain = 'primitive' AND archived_at IS NULL;

